<div class="section-toolbar"><a class="back-link" href="<?= e(url('inventory')) ?>">← Back to inventory</a><a class="button primary" href="<?= e(url('vehicle-edit', ['id' => $vehicle['Vehicle_ID']])) ?>">Edit vehicle</a></div>
<section class="panel vehicle-detail"><?php $photos = \NVRO\Services\VehiclePhotos::paths($vehicle); ?>
<div class="vehicle-gallery">
<?php if ($photos): ?><a class="gallery-cover" href="<?= e($photos[0]) ?>" target="_blank" rel="noopener"><img src="<?= e($photos[0]) ?>" alt="<?= e($vehicle['Brand_Name'] . ' ' . $vehicle['Model']) ?>"></a>
<?php if (count($photos) > 1): ?><div class="gallery-thumbs"><?php foreach ($photos as $index => $path): ?><a href="<?= e($path) ?>" target="_blank" rel="noopener"><img src="<?= e($path) ?>" alt="Vehicle photo <?= $index + 1 ?>"></a><?php endforeach; ?></div><?php endif; ?>
<?php else: ?><div class="photo-placeholder"><svg viewBox="0 0 48 36" aria-hidden="true"><rect x="3" y="3" width="42" height="30" rx="4"/><circle cx="15" cy="13" r="3"/><path d="m5 29 12-10 8 6 8-12 10 16"/></svg>No vehicle photos yet</div><?php endif; ?>
</div><div class="vehicle-info"><?= badge($vehicle['Availability_Status']) ?><h2><?= e($vehicle['Year'] . ' ' . $vehicle['Brand_Name'] . ' ' . $vehicle['Model']) ?></h2><p class="vehicle-price"><?= money($vehicle['Price']) ?></p><dl class="spec-grid"><?php foreach (['Color' => 'Color', 'Transmission' => 'Transmission', 'Fuel_Type' => 'Fuel type', 'Year' => 'Year'] as $key => $label): ?><div><dt><?= e($label) ?></dt><dd><?= e($vehicle[$key]) ?></dd></div><?php endforeach; ?></dl><div class="toolbar-actions"><a class="button secondary" href="<?= e(url('inquiry-new', ['vehicle' => $vehicle['Vehicle_ID']])) ?>">Record inquiry</a><?php if ($vehicle['Availability_Status'] === 'Available'): ?><a class="button primary" href="<?= e(url('test-drive-new', ['vehicle' => $vehicle['Vehicle_ID']])) ?>">Request test drive</a><?php endif; ?></div></div></section>
<div class="dashboard-grid"><section class="panel"><div class="panel-heading"><h2>Related inquiries</h2></div><div class="table-wrap"><table><thead><tr><th>Customer</th><th>Status</th><th>Details</th></tr></thead><tbody><?php foreach ($inquiries as $item): ?><tr><td><?= e($item['Customer_Name']) ?><small><?= e(date('M j, Y', strtotime($item['Inquiry_Date']))) ?></small></td><td><?= badge($item['Inquiry_Status']) ?></td><td><a class="text-link" href="<?= e(url('inquiry-edit', ['id' => $item['Inquiry_ID']])) ?>">View →</a></td></tr><?php endforeach; ?><?php if (!$inquiries): ?><tr><td colspan="3" class="empty-cell">No inquiries for this vehicle yet.</td></tr><?php endif; ?></tbody></table></div></section><section class="panel"><div class="panel-heading"><h2>Test-drive history</h2></div><div class="table-wrap"><table><thead><tr><th>Customer</th><th>Schedule</th><th>Status</th></tr></thead><tbody><?php foreach ($drives as $item): ?><tr><td><?= e($item['Customer_Name']) ?></td><td><?= e(date('M j, Y', strtotime($item['Scheduled_Date']))) ?><small><?= e(date('g:i A', strtotime($item['Scheduled_Date']))) ?></small></td><td><?= badge($item['Request_Status']) ?></td></tr><?php endforeach; ?><?php if (!$drives): ?><tr><td colspan="3" class="empty-cell">No test drives for this vehicle yet.</td></tr><?php endif; ?></tbody></table></div></section></div>
<?php if ($vehicle['Availability_Status'] !== 'Sold'): ?><section class="remove-record"><div><strong>Remove this vehicle</strong><p>Only incorrect or unwanted vehicles with no linked records can be removed.</p></div><form method="post" action="<?= e(url('vehicle-delete', ['id' => $vehicle['Vehicle_ID']])) ?>" data-confirm="Remove this vehicle permanently? This is only allowed when it has no linked records."><?= csrf() ?><button class="button danger-outline" type="submit">Remove vehicle</button></form></section><?php else: ?><p class="muted">This sold vehicle is retained for historical reference.</p><?php endif; ?>
